INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0120',120,'What kind of tea?','چه نوع چای؟','با kind درباره نوع یک چیز سؤال کن و جواب بده.','EN-A1-OUTCOME-0120',420,'24bdf12a26977c782ead8a38283f5ade57b2af7e9efc546ea691d04c159a77a1','validated','{"outcomeFa":"kind را به معنی «نوع» در عبارت what kind of در دو جمله کوتاه به کار ببری.","scenarioFa":"لیو و لیام در کتابخانه کنار میز نوشیدنی درباره دو نوع چای روی میز حرف می‌زنند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0119"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0120-KIND","form":"What kind of tea is this?","meaningFa":"پرسیدن نوع یک چیز"}],"supportLanguage":[{"form":"This tea is good.","meaningFa":"این چای خوب است."},{"form":"And that tea?","meaningFa":"آن چای چطور؟"}],"assessmentBoundary":"Only the bounded A1 noun sense of kind meaning a category/type is assessed.","transferPlan":{"mode":"same_lesson","intent":"Reuse what kind of with a second familiar drink."},"story":{"arcKey":"EN-A1-LIBRARY","sceneKey":"EN-A1-FACTORY-SCENE-0120","learnerRoleKey":"leo","participants":["liam","leo"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0115"],"continuesLessonKey":"EN-A1-L-0115","settingFa":"کتابخانه، میز نوشیدنی","storyBeatFa":"لیام درباره چای‌ها حرف می‌زند و لیو با kind نوع نوشیدنی‌ها را می‌پرسد."},"reviewLinks":[{"lessonKey":"EN-A1-L-0115","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning library arc is spaced by 5 Lessons and the played role changes from Liam to Leo."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0120","specHash":"7e191276046e69d99b717b68858b40a593dd8980d34c8936a9dabcf2e04d1d8d","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"what kind of tea is this","rationale":"Natural bounded construction for asking the category/type of a familiar item."},{"query":"what kind of drink is that","rationale":"Changed-noun construction preserving the same category sense."},{"query":"what kind of tea","rationale":"Exact target-collocation window extracted from the first learner question; natural A1 category frame around kind."},{"query":"what kind of drink","rationale":"Exact target-collocation window extracted from the transfer learner question; natural changed-noun frame around kind."}],"noNewGrammarReason":"Lexical-focus Lesson using familiar A1 sentence patterns; no new grammar is claimed."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
SET @lesson_id=(SELECT id FROM lessons WHERE level_id=@level_id AND lesson_key='EN-A1-L-0120' LIMIT 1);
DELETE FROM lesson_lexical_items WHERE lesson_id=@lesson_id;

-- Keep existing activities IDs; remove only keys absent from this Lesson source.
DELETE FROM activities WHERE lesson_id=@lesson_id AND activity_key NOT IN ('A01','A02','A03','A04','A05','A06');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),6) FROM activities WHERE lesson_id=@lesson_id);
UPDATE activities SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

